function put(root,tag,attrs,text){var n=svgNode(tag,attrs,text);root.appendChild(n);return n;}
function clear(svg,height,title,desc){svg.replaceChildren();var w=Math.max(280,Math.round(svg.parentElement.clientWidth-24));svg.setAttribute('viewBox','0 0 '+w+' '+height);put(svg,'title',{},title);put(svg,'desc',{},desc);return w;}
function axis(svg,w,h,xmin,xmax,ymax,timeAxis){var box={left:58,right:w-20,top:24,bottom:h-44};var x=function(t){return box.left+(t-xmin)/(xmax-xmin)*(box.right-box.left);};var y=function(v){return box.bottom-v/ymax*(box.bottom-box.top);};for(var i=0;i<=4;i++){var v=ymax*i/4;put(svg,'line',{x1:box.left,x2:box.right,y1:y(v),y2:y(v),class:'gridline'});put(svg,'text',{x:box.left-10,y:y(v)+4,'text-anchor':'end'},fmt(v,0));}
var ticks=w<480?3:5;for(var j=0;j<ticks;j++){var t=xmin+(xmax-xmin)*j/(ticks-1);put(svg,'text',{x:x(t),y:box.bottom+22,'text-anchor':j===0?'start':j===ticks-1?'end':'middle'},timeAxis(t));}
put(svg,'text',{x:box.left,y:15},'VIBR · escala ×1000');return {box:box,x:x,y:y};}
function linePath(points,x,y){var drawing=false;return points.map(function(p){if(p.y===null||!Number.isFinite(p.y)){drawing=false;return '';}var command=drawing?'L':'M';drawing=true;return command+x(p.x).toFixed(2)+' '+y(p.y).toFixed(2);}).join(' ');}
function controlState(selector,key,value){document.querySelectorAll(selector).forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset[key]===value));});}

/* 1. Cálculo didáctico, separado de la fuente PI. */
var calc={mode:'stable',factor:3.5,step:0};
function calcValues(){return calc.mode==='stable'?[16,18,20,20,22,24]:[8,14,20,20,26,32];}
function drawCalc(){var values=calcValues(),mean=values.reduce(function(a,b){return a+b;},0)/values.length,sigma=Math.sqrt(values.reduce(function(a,b){return a+Math.pow(b-mean,2);},0)/values.length),margin=calc.factor*sigma,limit=mean+margin;
el('meanNumber').textContent=fmt(mean,1);el('sigmaNumber').textContent=fmt(sigma,2);el('marginNumber').textContent=fmt(margin,2);el('limitNumber').textContent=fmt(limit,2);el('equation').textContent=fmt(mean,1)+' + '+fmt(calc.factor,1)+' × '+fmt(sigma,2)+' = '+fmt(limit,2);
el('factorConfigured').setAttribute('aria-pressed',String(calc.factor===3.5));el('factorClassic').setAttribute('aria-pressed',String(calc.factor===3));el('factorNote').textContent=calc.factor===3.5?'Este multiplicador coincide con la expresión revisada de tu instalación. Los números del ejemplo son didácticos.':'Esta comparación usa 3σ habitual. La configuración revisada de CLEAR/PI usa 3,5σ, no esta alternativa.';
var explanations=['Primero encontramos el centro: sumamos los seis valores y dividimos por seis. El promedio es '+fmt(mean,1)+'.','Después medimos cuánto se separan los valores del promedio. Esa variación típica es σ = '+fmt(sigma,2)+'.','Multiplicamos la desviación por '+fmt(calc.factor,1)+'. El margen resultante es '+fmt(margin,2)+'.','Sumamos el margen al promedio. En este ejemplo, el límite queda en '+fmt(limit,2)+'. Superarlo sólo cumple la comparación; todavía falta la espera.'];
el('calcExplain').textContent=explanations[calc.step];el('calcNext').textContent=calc.step===3?'Volver a empezar ↺':'Siguiente paso →';for(var i=0;i<4;i++)el('calcBit'+i).classList.toggle('is-active',i<=calc.step);
var svg=el('calcChart'),w=clear(svg,230,'Media y dispersión: ejemplo didáctico','Seis valores inventados; promedio, distancias y límite de ejemplo.'),left=34,right=w-24,top=25,bottom=185,ymax=Math.max(40,limit*1.15),x=function(i){return left+i*(right-left)/5;},y=function(v){return bottom-v/ymax*(bottom-top);};
put(svg,'line',{x1:left,x2:right,y1:y(mean),y2:y(mean),stroke:'#17576a','stroke-width':2});
put(svg,'text',{x:left,y:15},'Línea horizontal: media '+fmt(mean,1));
values.forEach(function(v,i){if(calc.step>=1)put(svg,'line',{x1:x(i),x2:x(i),y1:y(v),y2:y(mean),stroke:'#b6a4d4','stroke-width':2,'stroke-dasharray':'3 3'});put(svg,'circle',{cx:x(i),cy:y(v),r:6,fill:'#17576a'});put(svg,'text',{x:x(i),y:y(v)+(v<mean?21:-13),'text-anchor':'middle',class:'value-label'},String(v));put(svg,'text',{x:x(i),y:214,'text-anchor':'middle'},'Dato '+(i+1));});
if(calc.step>=3){put(svg,'line',{x1:left,x2:right,y1:y(limit),y2:y(limit),stroke:'#7650b1','stroke-width':2,'stroke-dasharray':'6 4'});put(svg,'text',{x:right,y:y(limit)-10,'text-anchor':'end',class:'value-label'},'Umbral '+fmt(limit,2));}}
document.querySelectorAll('[data-spread]').forEach(function(b){b.addEventListener('click',function(){calc.mode=b.dataset.spread;controlState('[data-spread]','spread',calc.mode);drawCalc();});});
el('calcNext').onclick=function(){calc.step=(calc.step+1)%4;drawCalc();};el('calcReset').onclick=function(){calc.step=0;drawCalc();};el('factorConfigured').onclick=function(){calc.factor=3.5;drawCalc();};el('factorClassic').onclick=function(){calc.factor=3;drawCalc();};

/* 2. Episodio de LH-945; reloj y condición separados de la curva esquemática. */
var base=Date.parse('2026-10-26T03:00:00-03:00'),on=46+.192/60,qualify=on+180,sent=226+21.486/60,off=256+15.142/60,threshold=67.21459329128265;
var event={t:0,scenario:'real',playing:false,last:0,raf:0};
function episodePoints(){if(event.scenario==='short')return[{x:0,y:38},{x:on,y:38},{x:on,y:114},{x:106,y:99},{x:on+120,y:99},{x:on+120,y:38},{x:270,y:38}];return[{x:0,y:38},{x:on,y:38},{x:on,y:114},{x:105,y:114},{x:105,y:103},{x:136,y:103},{x:136,y:99},{x:195,y:99},{x:195,y:77},{x:255,y:77},{x:off,y:77},{x:off,y:38},{x:270,y:38}];}
function currentValue(){var points=episodePoints(),v=points[0].y;points.forEach(function(p){if(p.x<=event.t)v=p.y;});return v;}
function eventStatus(){var real=event.scenario==='real',end=real?off:on+120;if(event.t<on)return{title:'Por debajo del umbral',body:'Todavía no empezó el episodio. La comparación no está activa.',progress:0,done:0};
if(!real&&event.t>=end)return{title:'La espera se interrumpe',body:'En esta simulación la vibración baja después de 2 horas. No completó las 3 horas: este disparador no habilita el aviso.',progress:0,done:1};
if(real&&event.t>=off)return{title:'El evento quedó cerrado',body:'El episodio real cerró a las 07:16:15. PI ya había registrado el envío a las 06:46:21. Cerrar no borra ese aviso.',progress:180,done:5};
if(real&&event.t>=sent)return{title:'PI registró el envío',body:'La anotación del servicio indica envío a las 06:46:21. Esto no confirma recepción ni lectura del correo.',progress:180,done:4};
if(real&&event.t>=qualify)return{title:'Se cumplieron las 3 horas',body:'La condición ya sostuvo la espera requerida. El evento se asocia al inicio de las 03:46. El envío real se registró segundos después.',progress:180,done:3};
return{title:'Superación sostenida: esperando',body:'La comparación es verdadera, pero el tiempo todavía no alcanza. No basta con estar sobre el límite en una sola lectura.',progress:Math.max(0,event.t-on),done:1};}
function drawEvent(){var svg=el('eventChart'),w=clear(svg,320,'Episodio y espera de tres horas','Reloj guiado del evento real o de un pico breve simulado; la curva es esquemática.'),a=axis(svg,w,320,0,270,160,function(t){return localTime(base+t*60000);}),points=episodePoints(),end=event.scenario==='real'?off:on+120;
put(svg,'rect',{x:a.x(on),y:a.box.top,width:Math.max(0,a.x(end)-a.x(on)),height:a.box.bottom-a.box.top,fill:'#7650b110'});
put(svg,'line',{x1:a.box.left,x2:a.box.right,y1:a.y(threshold),y2:a.y(threshold),class:'threshold'});
put(svg,'text',{x:a.box.right,y:a.y(threshold)-8,'text-anchor':'end'},'Límite PI: 67,215');
put(svg,'path',{d:linePath(points,a.x,a.y),fill:'none',stroke:'#c6d5dd','stroke-width':2});
var visible=points.filter(function(p){return p.x<=event.t;});if(visible.length){visible.push({x:event.t,y:currentValue()});put(svg,'path',{d:linePath(visible,a.x,a.y),class:'plot-line'});}
put(svg,'line',{x1:a.x(event.t),x2:a.x(event.t),y1:a.box.top,y2:a.box.bottom,stroke:'#183c47','stroke-width':1.5});
put(svg,'circle',{cx:a.x(event.t),cy:a.y(currentValue()),r:6,class:'time-dot'});
if(event.scenario==='real'){put(svg,'line',{x1:a.x(qualify),x2:a.x(qualify),y1:a.box.top,y2:a.box.bottom,stroke:'#7650b1','stroke-dasharray':'3 5'});put(svg,'text',{x:a.x(qualify)-6,y:a.box.top+14,'text-anchor':'end'},'Cumple 3 h');}
el('eventClock').textContent=localTime(base+event.t*60000,true);el('eventTime').value=event.t;var state=eventStatus();if(el('eventStateTitle').textContent!==state.title)el('eventStateTitle').textContent=state.title;if(el('eventStateText').textContent!==state.body)el('eventStateText').textContent=state.body;el('waitFill').style.width=Math.min(100,state.progress/180*100)+'%';el('waitBar').setAttribute('aria-valuenow',Math.min(180,Math.floor(state.progress)));el('waitElapsed').textContent=Math.min(180,Math.floor(state.progress))+' de 180 minutos';el('scenarioLabel').textContent=event.scenario==='real'?'Reconstrucción guiada de un evento real':'Simulación didáctica: no es el episodio real';el('eventStages').querySelectorAll('li').forEach(function(li,i){li.classList.toggle('done',i<state.done);});}
function eventStop(){event.playing=false;cancelAnimationFrame(event.raf);el('eventPlay').textContent=reducedMotion?'Avanzar sin animación':'▶ Reproducir';}
function eventTick(now){if(!event.playing)return;if(!event.last)event.last=now;var delta=Math.min(80,now-event.last);event.last=now;event.t=Math.min(270,event.t+delta/1000*(270/28)*Number(el('eventSpeed').value));drawEvent();if(event.t>=270){eventStop();return;}event.raf=requestAnimationFrame(eventTick);}
el('eventPlay').onclick=function(){if(reducedMotion){var steps=[on,qualify,sent,off,270];event.t=steps.find(function(t){return t>event.t+.00001;})||0;drawEvent();return;}if(event.playing){eventStop();return;}if(event.t>=270)event.t=0;event.playing=true;event.last=0;el('eventPlay').textContent='Ⅱ Pausar';event.raf=requestAnimationFrame(eventTick);};
el('eventReset').onclick=function(){eventStop();event.t=0;drawEvent();};el('eventTime').oninput=function(){eventStop();event.t=Number(this.value);drawEvent();};
document.querySelectorAll('[data-jump]').forEach(function(b){b.onclick=function(){eventStop();event.t=Number(b.dataset.jump);drawEvent();};});
document.querySelectorAll('[data-scenario]').forEach(function(b){b.onclick=function(){eventStop();event.scenario=b.dataset.scenario;event.t=0;controlState('[data-scenario]','scenario',event.scenario);drawEvent();};});

/* 3. Gráfico construido con los registros SQL reales incluidos en el archivo. */
var historyRows=DATA.series.map(function(p){return{x:stamp(p.FECHA),y:number(p.VIBR)};}).filter(function(p){return Number.isFinite(p.x);});
var samples=historyRows.filter(function(p){return p.y!==null&&Number.isFinite(p.y);});
var episodes=DATA.events.map(function(p){return{start:stamp(p.INICIO),end:stamp(p.FIN),threshold:number(p.UMBRAL_INICIO)};});
var history={percent:100,zoom:false,playing:false,last:0,raf:0};
el('sampleCount').textContent=historyRows.length;
el('historyDataNote').textContent='Datos incluidos: '+historyRows.length+' registros SQL; '+samples.length+' lecturas VIBR válidas y '+(historyRows.length-samples.length)+' registro sin VIBR. El dato faltante se deja como hueco, no se transforma en cero.';
function drawHistory(){if(!samples.length)return;var svg=el('historyChart'),w=clear(svg,390,'Vibración real LH-945 y episodios PI','Registros SQL reales del 25 y 26/10/2026, franjas PI y límites CLEAR de la captura.'),xmin=samples[0].x,xmax=samples[samples.length-1].x,maxValue=Math.max.apply(null,samples.map(function(p){return p.y;})),ymax=history.zoom?Math.ceil(maxValue*1.04/100)*100:Math.ceil(Math.max(maxValue,number(DATA.state.UMBRAL_CRITICO)||574)*1.04/100)*100,a=axis(svg,w,390,xmin,xmax,ymax,function(t){return dateTime(t);}),cursor=xmin+(xmax-xmin)*history.percent/100;
var defs=put(svg,'defs',{}),clip=put(defs,'clipPath',{id:'real-reveal'});put(clip,'rect',{x:a.box.left,y:a.box.top,width:Math.max(0,a.x(cursor)-a.box.left),height:a.box.bottom-a.box.top});
var content=put(svg,'g',{'clip-path':'url(#real-reveal)'});
episodes.forEach(function(e){var start=Math.max(xmin,e.start),end=Math.min(xmax,e.end||xmax);if(end<start)return;put(content,'rect',{x:a.x(start),y:a.box.top,width:Math.max(0,a.x(end)-a.x(start)),height:a.box.bottom-a.box.top,fill:'#7650b119'});put(content,'line',{x1:a.x(start),x2:a.x(end),y1:a.y(e.threshold),y2:a.y(e.threshold),class:'threshold'});});
if(!history.zoom)[{v:number(DATA.state.UMBRAL_ALERTA)||410,color:'#b86809'},{v:number(DATA.state.UMBRAL_CRITICO)||574,color:'#b93240'}].forEach(function(ref){put(svg,'line',{x1:a.box.left,x2:a.box.right,y1:a.y(ref.v),y2:a.y(ref.v),stroke:ref.color,'stroke-width':1.5,'stroke-dasharray':'6 5'});});
put(content,'path',{d:linePath(historyRows,a.x,a.y),class:'plot-line'});
samples.forEach(function(p){if(p.x<=cursor)put(content,'circle',{cx:a.x(p.x),cy:a.y(p.y),r:2.5,fill:'#2f80a3'});});
put(svg,'line',{x1:a.x(cursor),x2:a.x(cursor),y1:a.box.top,y2:a.box.bottom,stroke:'#183c47','stroke-width':1.2});
var nearest=samples.reduce(function(best,p){return Math.abs(p.x-cursor)<Math.abs(best.x-cursor)?p:best;},samples[0]);put(svg,'circle',{cx:a.x(nearest.x),cy:a.y(nearest.y),r:5,class:'time-dot'});
el('historyReadout').textContent='Lectura más cercana: '+dateTime(nearest.x)+' · VIBR '+fmt(nearest.y,1)+' · escala ×1000';el('historyTime').value=history.percent;el('historyZoom').setAttribute('aria-pressed',String(history.zoom));el('historyZoom').textContent=history.zoom?'Volver a comparar con CLEAR':'Acercar la zona PI';el('zoomLabel').textContent=history.zoom?'Acercamiento: los límites CLEAR quedan fuera de vista':'Comparación completa';}
function historyStop(){history.playing=false;cancelAnimationFrame(history.raf);el('historyPlay').textContent=reducedMotion?'Avanzar el gráfico por tramos':'▶ Reproducir el gráfico real';}
function historyTick(now){if(!history.playing)return;if(!history.last)history.last=now;var delta=Math.min(80,now-history.last);history.last=now;history.percent=Math.min(100,history.percent+delta/1000*(100/20));drawHistory();if(history.percent>=100){historyStop();return;}history.raf=requestAnimationFrame(historyTick);}
el('historyPlay').onclick=function(){if(reducedMotion){history.percent=history.percent>=100?0:Math.min(100,history.percent+25);drawHistory();return;}if(history.playing){historyStop();return;}if(history.percent>=100)history.percent=0;history.playing=true;history.last=0;el('historyPlay').textContent='Ⅱ Pausar el gráfico';history.raf=requestAnimationFrame(historyTick);};el('historyTime').oninput=function(){historyStop();history.percent=Number(this.value);drawHistory();};el('historyComplete').onclick=function(){historyStop();history.percent=100;drawHistory();};el('historyZoom').onclick=function(){history.zoom=!history.zoom;drawHistory();};
document.querySelectorAll('[data-enlarge]').forEach(function(img){img.tabIndex=0;img.setAttribute('role','button');img.setAttribute('aria-label','Ampliar: '+img.alt);function openImage(){el('largeImage').src=img.src;el('largeImage').alt=img.alt;el('imageDialog').showModal();}img.onclick=openImage;img.onkeydown=function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();openImage();}};});el('imageClose').onclick=function(){el('imageDialog').close();};
function syncMotion(){el('motionToggle').textContent=reducedMotion?'Activar animaciones':'Usar pasos sin movimiento';el('motionToggle').setAttribute('aria-pressed',String(!reducedMotion));el('motionNote').textContent=reducedMotion?'Tu dispositivo prefiere menos movimiento. Podés avanzar por pasos o activar las animaciones sólo en esta guía.':'El movimiento empieza al pulsar Reproducir. Podés pausar o avanzar por pasos cuando quieras.';}
el('motionToggle').onclick=function(){reducedMotion=!reducedMotion;eventStop();historyStop();syncMotion();};
document.addEventListener('visibilitychange',function(){if(document.hidden){eventStop();historyStop();}});
var resizeTimer;window.addEventListener('resize',function(){clearTimeout(resizeTimer);resizeTimer=setTimeout(function(){drawCalc();drawEvent();drawHistory();},80);});
syncMotion();eventStop();historyStop();drawCalc();drawEvent();drawHistory();
})();
</script>
</body>
</html>
